  who: [
    [1,"Endlich! Sie ist Bein von meinem Bein und Fleisch von meinem Fleisch.","Adam",["Noah","Abraham","Kain"],"1. Mose 2,23"],
    [1,"Die Schlange hat mich getäuscht, da habe ich gegessen.","Eva",["Sara","Rebekka","Mirjam"],"1. Mose 3,13"],
    [2,"Meinen Regenbogen setze ich in die Wolken. Er ist das Zeichen meines Bundes.","Gott",["Noah","Mose","Abraham"],"1. Mose 9,13"],
    [11,"Gott selbst wird für das Lamm sorgen.","Abraham",["Isaak","Jakob","Lot"],"1. Mose 22,8"],
    [11,"Hier sind Feuer und Holz – aber wo ist das Lamm?","Isaak",["Ismael","Esau","Lot"],"1. Mose 22,7"],
    [11,"Gott hat mich zum Lachen gebracht! Alle, die es hören, lachen mit mir.","Sara",["Rebekka","Rahel","Hagar"],"1. Mose 21,6"],
    [12,"Ihr wolltet mir Böses tun, aber Gott hat es zum Guten gewendet.","Josef",["Jakob","Juda","Ruben"],"1. Mose 50,20"],
    [12,"Finden wir je einen Mann wie ihn, in dem Gottes Geist ist?","Pharao",["Potifar","Jakob","Juda"],"1. Mose 41,38"],
    [3,"Wer bin ich denn, dass ich zum Pharao gehen soll?","Mose",["Aaron","Josua","Josef"],"2. Mose 3,11"],
    [3,"Wer ist denn der HERR, dass ich auf ihn hören sollte?","Pharao",["Potifar","Goliat","Nebukadnezar"],"2. Mose 5,2"],
    [3,"Singt dem HERRN, denn er hat einen herrlichen Sieg errungen!","Mirjam",["Debora","Hanna","Ester"],"2. Mose 15,21"],
    [4,"Du sollst keine anderen Götter neben mir haben.","Gott",["Mose","Aaron","Josua"],"2. Mose 20,3"],
    [4,"Das ist zu schwer für dich allein. Such dir Helfer!","Jitro",["Aaron","Kaleb","Josua"],"2. Mose 18,17-21"],
    [5,"Ich aber und meine Familie, wir wollen dem HERRN dienen.","Josua",["Mose","Kaleb","Gideon"],"Josua 24,15"],
    [5,"Der HERR, euer Gott, ist Gott oben im Himmel und unten auf der Erde.","Rahab",["Rut","Debora","Mirjam"],"Josua 2,11"],
    [19,"Meine Familie ist die ärmste, und ich bin der Jüngste im Haus meines Vaters.","Gideon",["Simson","Barak","Jonatan"],"Richter 6,15"],
    [20,"Vom Fresser kam Speise, vom Starken kam Süßes.","Simson",["Gideon","Samuel","Delila"],"Richter 14,14"],
    [20,"Simson, die Philister kommen!","Delila",["Rut","Isebel","Michal"],"Richter 16,9"],
    [13,"Wo du hingehst, da gehe ich auch hin. Dein Volk ist mein Volk, und dein Gott ist mein Gott.","Rut",["Noomi","Orpa","Ester"],"Rut 1,16"],
    [13,"Nennt mich nicht Noomi, nennt mich Mara.","Noomi",["Rut","Orpa","Hanna"],"Rut 1,20"],
    [13,"Der HERR sei mit euch!","Boas",["Elimelech","Obed","Isai"],"Rut 2,4"],
    [6,"Du kommst mit dem Schwert, ich aber komme im Namen des HERRN.","David",["Saul","Jonatan","Samuel"],"1. Samuel 17,45"],
    [6,"Bin ich denn ein Hund, dass du mit Stöcken zu mir kommst?","Goliat",["Saul","Eliab","Abner"],"1. Samuel 17,43"],
    [6,"Der Mensch sieht, was vor Augen ist, der HERR aber sieht das Herz an.","Gott",["Samuel","Isai","David"],"1. Samuel 16,7"],
    [14,"Wie lange wollt ihr noch hin und her schwanken? Ist der HERR Gott, dann folgt ihm!","Elia",["Elisa","Ahab","Obadja"],"1. Könige 18,21"],
    [14,"Ich habe nur noch eine Handvoll Mehl im Topf und ein wenig Öl im Krug.","Die Witwe von Sarepta",["Isebel","Noomi","Hanna"],"1. Könige 17,12"],
    [15,"Ich wusste ja, dass du ein gnädiger und barmherziger Gott bist, geduldig und voller Güte.","Jona",["Elia","Daniel","Jeremia"],"Jona 4,2"],
    [15,"Wer weiß, vielleicht hat Gott doch noch Erbarmen mit uns?","Der König von Ninive",["Nebukadnezar","Pharao","Darius"],"Jona 3,9"],
    [7,"Mein Gott hat seinen Engel gesandt und den Löwen das Maul verschlossen.","Daniel",["Schadrach","Darius","Hesekiel"],"Daniel 6,22"],
    [7,"Seht doch! Ich sehe vier Männer frei mitten im Feuer umhergehen!","Nebukadnezar",["Darius","Belschazzar","Daniel"],"Daniel 3,25"],
    [16,"Wer weiß, ob du nicht gerade für eine Zeit wie diese Königin geworden bist?","Mordechai",["Haman","Ahasveros","Nehemia"],"Ester 4,14"],
    [16,"Ich gehe zum König. Komme ich um, so komme ich um.","Ester",["Rut","Waschti","Debora"],"Ester 4,16"],
    [21,"Kommt, lasst uns die Mauer Jerusalems wieder aufbauen!","Nehemia",["Esra","Serubbabel","Haggai"],"Nehemia 2,17"],
    [8,"Ich bin die Dienerin des Herrn. Es soll geschehen, wie du gesagt hast.","Maria",["Elisabet","Hanna","Marta"],"Lukas 1,38"],
    [8,"Wo ist der neugeborene König der Juden? Wir haben seinen Stern gesehen.","Die Weisen",["Die Hirten","König Herodes","Simeon"],"Matthäus 2,2"],
    [8,"Kommt, wir gehen nach Bethlehem und sehen uns an, was dort geschehen ist!","Die Hirten",["Die Weisen","Maria und Josef","Zacharias"],"Lukas 2,15"],
    [9,"Kommt, folgt mir nach! Ich will euch zu Menschenfischern machen.","Jesus",["Johannes der Täufer","Petrus","Andreas"],"Matthäus 4,19"],
    [9,"Herr, rette mich!","Petrus",["Johannes","Andreas","Thomas"],"Matthäus 14,30"],
    [9,"Seht, das ist Gottes Lamm, das die Sünde der Welt wegnimmt!","Johannes der Täufer",["Petrus","Andreas","Nikodemus"],"Johannes 1,29"],
    [22,"Vater, ich habe gegen den Himmel und gegen dich gesündigt.","Der verlorene Sohn",["Der ältere Bruder","Der barmherzige Samariter","Zachäus"],"Lukas 15,21"],
    [22,"Freut euch mit mir! Ich habe mein verlorenes Schaf gefunden!","Der Hirte",["Die Frau mit der Münze","Der Vater","Der Samariter"],"Lukas 15,6"],
    [22,"Herr, die Hälfte von allem, was ich habe, gebe ich den Armen.","Zachäus",["Matthäus","Nikodemus","Bartimäus"],"Lukas 19,8"],
    [10,"Ich habe den Herrn gesehen!","Maria Magdalena",["Marta","Salome","Johanna"],"Johannes 20,18"],
    [10,"Mein Herr und mein Gott!","Thomas",["Petrus","Johannes","Philippus"],"Johannes 20,28"],
    [17,"Silber und Gold habe ich nicht. Aber was ich habe, das gebe ich dir.","Petrus",["Johannes","Paulus","Stephanus"],"Apostelgeschichte 3,6"],
    [17,"Kehrt um und lasst euch alle taufen auf den Namen von Jesus Christus!","Petrus",["Matthias","Philippus","Jakobus"],"Apostelgeschichte 2,38"],
    [18,"Saul, Saul, warum verfolgst du mich?","Jesus",["Hananias","Stephanus","Barnabas"],"Apostelgeschichte 9,4"],
    [18,"Ihr Herren, was muss ich tun, damit ich gerettet werde?","Der Gefängniswärter in Philippi",["Kornelius","Festus","Felix"],"Apostelgeschichte 16,30"],
    [18,"Seid mutig! Ich vertraue Gott.","Paulus",["Lukas","Silas","Barnabas"],"Apostelgeschichte 27,25"]
  ],
